def adapt(argv):
 return [s.replace('/tmp/fridadev-m6-proof-20261007',str(ROOT)).replace('fridadev-m6-proof','fridadev-m6-aud03-proof').replace('20261006','20261007') for s in argv]
def record(label,argv):
 start=datetime.datetime.now(datetime.timezone.utc).isoformat(); t=time.monotonic()
 p=subprocess.run(argv,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
 log=ROOT/(label+'.log');log.write_bytes(p.stdout)
 r=dict(label=label,argv=argv,exit=p.returncode,started_utc=start,wall_seconds=round(time.monotonic()-t,3),log_sha256=hashlib.sha256(p.stdout).hexdigest(),log_bytes=len(p.stdout))
 text=p.stdout.decode(errors='replace')
 if '-m' in argv and 'unittest' in argv:
  r['kind']='python';r['test_ids']=re.findall(r'^test\S* \(([^)]+)\) \.\.\. ',text,re.M)
  m=re.search(r'Ran (\d+) tests? in ([\d.]+)s',text);r['tests']=int(m[1]) if m else None;r['runner_seconds']=float(m[2]) if m else None
  summary=text[text.rfind('Ran '):]
  r['skips']=int(re.search(r'skipped=(\d+)',summary)[1]) if re.search(r'skipped=(\d+)',summary) else 0
  for key in ('errors','failures'):
   match=re.search(key+r'=(\d+)',summary);r[key]=int(match[1]) if match else 0
 elif '--test' in argv:
  r['kind']='frontend';r['test_ids']=[s.replace('\\#','#') for s in re.findall(r'^# Subtest: (.*)$',text,re.M)]
  for k in ('tests','pass','fail','skipped','cancelled'):
   m=re.search(r'^# '+k+r' (\d+)$',text,re.M);r[k]=int(m[1]) if m else None
  r['skips']=r.get('skipped')
 (ROOT/(label+'.json')).write_text(json.dumps(r,indent=2)+'\n')
 print(json.dumps({k:v for k,v in r.items() if k not in ('argv','test_ids')},sort_keys=True),flush=True)
 if p.returncode:print(text[-4500:],flush=True)
 return p.returncode
if __name__=='__main__':
 mode=sys.argv[1]
 if mode=='setup':
  for key in sys.argv[2:]:
   argv=adapt(D['isolation']['setup_records'][key]['argv'])
   for x in argv:
    if x.endswith(':/var/run/postgresql'):Path(x.split(':')[0]).mkdir(exist_ok=True)
   if record(key,argv):sys.exit(1)
 elif mode=='group':
  label=sys.argv[2]; key=sys.argv[3];section=sys.argv[4] if len(sys.argv)>4 else 'selections'
  sys.exit(record(label,adapt(D['final'][section][key]['argv'])))
 elif mode=='py':
  label=sys.argv[2];argv=adapt(D['final']['selections']['final-baseline-sql']['argv']);ix=argv.index('python');argv=argv[:ix]+['python',*sys.argv[3:]];argv[argv.index('-w')+1]='/workspace/app'
  if '/proof/aud:ro' not in argv:argv[argv.index('-w'):argv.index('-w')]=['-v',str(ROOT)+':/proof/aud:ro']
  sys.exit(record(label,argv))
 elif mode=='node':
  label=sys.argv[2];argv=adapt(D['final']['selections']['final-baseline-chromium_historical']['argv']);ix=argv.index('node');argv=argv[:ix]+['node',*sys.argv[3:]];argv[argv.index('-w'):argv.index('-w')]=['-v',str(ROOT)+':/proof/aud:ro']
  sys.exit(record(label,argv))
 elif mode=='argv':sys.exit(record(sys.argv[2],json.loads(sys.argv[3])))

