import json,threading
from contextlib import contextmanager
from types import SimpleNamespace
from unittest.mock import patch
from tests.integration.document_workshop import test_action_cancellation_pause_postgresql as proof
case=proof.ActionCancellationPausePostgresqlTests();case.setUp()
failed=threading.Event();observed={}
actions=case.case.actions
real_check=actions.check_active
real_pause=case.case.external_lock_supervision_pause
def check(*args,**kwargs):
    try:return real_check(*args,**kwargs)
    except Exception as error:
        if threading.current_thread().name!='document-preparation':
            observed['guard_error']=type(error).__name__;failed.set()
        raise
@contextmanager
def delayed_pause():
    with real_pause() as checks:
        def pause():
            assert failed.wait(3),'guard did not reach the held watchdog before pause'
            checks.pause()
        yield SimpleNamespace(pause=pause,resume=checks.resume,snapshot=checks.snapshot,condition=checks.condition)
try:
    with patch.object(actions,'check_active',check),patch.object(case.case,'external_lock_supervision_pause',delayed_pause):
        try:case.prove_pause(omit_drain=False)
        except AssertionError as error:
            observed['positive_rejected']=True
            observed['assertion_kind']='no_control_at_paused_admission' if 'no real control arrived' in str(error) else 'other'
        else:raise AssertionError('expected forced pre-pause instrumentation contention absent')
    assert observed.get('guard_error')=='LockNotAvailable',observed
    print('P3_M6_AUD_03_PRE_PAUSE '+json.dumps(observed,sort_keys=True))
finally:case.doCleanups()
